 78→/**
 79→ * Wraps native fetch to work around grammY's polyfilled AbortController.
 80→ * grammY uses abort-controller polyfill whose AbortSignal fails instanceof
 81→ * checks in Node 24+ native fetch. This wrapper re-creates a native
 82→ * AbortSignal from the polyfilled one before passing it to fetch.
 83→ */
 84→function patchedFetch(
 85→  input: RequestInfo | URL,
 86→  init?: RequestInit,
 87→): Promise<Response> {
 88→  if (init?.signal && !(init.signal instanceof AbortSignal)) {
 89→    const nativeController = new AbortController();
 90→    const polyfillSignal = init.signal as unknown as {
 91→      aborted: boolean;
 92→      addEventListener: (event: string, fn: () => void) => void;
 93→    };
 94→    if (polyfillSignal.aborted) {
 95→      nativeController.abort();
 96→    } else {
 97→      polyfillSignal.addEventListener("abort", () => nativeController.abort());
 98→    }
 99→    init = { ...init, signal: nativeController.signal };
100→  }
101→  return fetch(input, init);
102→}
