140→  async start(): Promise<void> {
141→    this.bot = new Bot(this.telegramConfig.botToken, { client: { fetch: patchedFetch } });
142→    this.fileService = this.core.fileService;
143→
144→    // Initialize extracted managers
145→    this.toolTracker = new ToolCallTracker(this.bot, this.telegramConfig.chatId, this.sendQueue);
146→    this.draftManager = new DraftManager(this.bot, this.telegramConfig.chatId, this.sendQueue);
147→    this.skillManager = new SkillCommandManager(
148→      this.bot,
149→      this.telegramConfig.chatId,
150→      this.sendQueue,
151→      this.core.sessionManager,
152→    );
153→
154→    // Global error handler — prevent unhandled errors from crashing the bot
155→    this.bot.catch((err) => {
156→      const rootCause = err.error instanceof Error ? err.error : err;
157→      log.error({ err: rootCause }, "Telegram bot error");
158→    });
159→
160→    // Auto-retry on 429 (Too Many Requests)
161→    this.bot.api.config.use(async (prev, method, payload, signal) => {
162→      const maxRetries = 3;
163→      for (let attempt = 0; attempt <= maxRetries; attempt++) {
164→        const result = await prev(method, payload, signal);
165→        if (
166→          result.ok ||
167→          (result as { error_code?: number }).error_code !== 429 ||
168→          attempt === maxRetries
169→        ) {
170→          return result;
171→        }
172→        const retryAfter =
173→          ((result as { parameters?: { retry_after?: number } }).parameters
174→            ?.retry_after ?? 5) + 1;
175→        const rateLimitedMethods = ['sendMessage', 'editMessageText', 'editMessageReplyMarkup'];
176→        if (rateLimitedMethods.includes(method)) {
177→          this.sendQueue.onRateLimited();
178→        }
179→        log.warn(
180→          { method, retryAfter, attempt: attempt + 1 },
181→          "Rate limited by Telegram, retrying",
182→        );
183→        await new Promise((r) => setTimeout(r, retryAfter * 1000));
184→      }
185→      return prev(method, payload, signal);
186→    });
187→
188→    // Ensure allowed_updates includes callback_query on every poll
189→    this.bot.api.config.use((prev, method, payload, signal) => {
190→      if (method === "getUpdates") {
191→        const p = payload as Record<string, unknown>;
192→        p.allowed_updates = (p.allowed_updates as string[] | undefined) ?? [
193→          "message",
194→          "callback_query",
195→        ];
196→      }
197→      return prev(method, payload, signal);
198→    });
199→
200→    // Register static commands for Telegram autocomplete
201→    await this.bot.api.setMyCommands(STATIC_COMMANDS, {
202→      scope: { type: "chat", chat_id: this.telegramConfig.chatId },
203→    });
204→
205→    // Middleware: only accept updates from configured chatId
206→    this.bot.use((ctx, next) => {
207→      const chatId = ctx.chat?.id ?? ctx.callbackQuery?.message?.chat?.id;
208→      if (chatId !== this.telegramConfig.chatId) return;
209→      return next();
210→    });
211→
212→    // Ensure system topics exist
213→    const topics = await ensureTopics(
214→      this.bot,
215→      this.telegramConfig.chatId,
216→      this.telegramConfig,
217→      async (updates) => {
218→        await this.core.configManager.save({
219→          channels: { telegram: updates },
220→        });
221→      },
222→    );
223→    this.notificationTopicId = topics.notificationTopicId;
224→    this.assistantTopicId = topics.assistantTopicId;
225→
226→    // Setup permission handler
227→    this.permissionHandler = new PermissionHandler(
228→      this.bot,
229→      this.telegramConfig.chatId,
230→      (sessionId) =>
231→        this.core.sessionManager.getSession(sessionId),
232→      (notification) => this.sendNotification(notification),
233→    );
234→
235→    // Callback registration order matters!
236→    setupDangerousModeCallbacks(this.bot, this.core as OpenACPCore);
237→    setupActionCallbacks(
238→      this.bot,
239→      this.core as OpenACPCore,
240→      this.telegramConfig.chatId,
241→      () => this.assistantSession?.id,
242→    );
243→    setupIntegrateCallbacks(this.bot, this.core as OpenACPCore);
244→    setupMenuCallbacks(
245→      this.bot,
246→      this.core as OpenACPCore,
247→      this.telegramConfig.chatId,
248→      { notificationTopicId: this.notificationTopicId, assistantTopicId: this.assistantTopicId },
249→      () => {
250→        if (!this.assistantSession) return undefined;
251→        return {
252→          topicId: this.assistantTopicId,
253→          enqueuePrompt: (p: string) => this.assistantSession!.enqueuePrompt(p),
254→        };
255→      },
256→    );
257→    setupCommands(
258→      this.bot,
259→      this.core as OpenACPCore,
260→      this.telegramConfig.chatId,
261→      {
262→        topicId: this.assistantTopicId,
263→        getSession: () => this.assistantSession,
264→        respawn: async () => {
265→          if (this.assistantSession) {
266→            await this.assistantSession.destroy();
267→            this.assistantSession = null;
268→          }
269→          const { session, ready } = await spawnAssistant(
270→            this.core as OpenACPCore,
271→            this,
272→            this.assistantTopicId,
273→          );
274→          this.assistantSession = session;
275→          this.assistantInitializing = true;
276→          ready.then(() => { this.assistantInitializing = false; });
277→        },
278→      },
279→    );
280→    this.permissionHandler.setupCallbackHandler();
281→
282→    // /handoff command
283→    this.bot.command("handoff", async (ctx) => {
284→      const threadId = ctx.message?.message_thread_id;
285→      if (!threadId) return;
286→
287→      if (threadId === this.notificationTopicId || threadId === this.assistantTopicId) {
288→        await ctx.reply("This command only works in session topics.", {
289→          message_thread_id: threadId,
290→        });
291→        return;
292→      }
293→
294→      const session = this.core.sessionManager.getSessionByThread("telegram", String(threadId));
295→      const record = session ? undefined : this.core.sessionManager.getRecordByThread("telegram", String(threadId));
296→
297→      const agentName = session?.agentName ?? record?.agentName;
298→      const agentSessionId = session?.agentSessionId ?? record?.agentSessionId;
299→
300→      if (!agentName || !agentSessionId) {
301→        await ctx.reply("No session found for this topic.", {
302→          message_thread_id: threadId,
303→        });
304→        return;
305→      }
306→
307→      const { getAgentCapabilities } = await import("../../core/agent-registry.js");
308→      const caps = getAgentCapabilities(agentName);
309→
310→      if (!caps.supportsResume || !caps.resumeCommand) {
311→        await ctx.reply("This agent does not support session transfer.", {
312→          message_thread_id: threadId,
313→        });
314→        return;
315→      }
316→
317→      const command = caps.resumeCommand(agentSessionId);
318→
319→      await ctx.reply(
320→        `Run this in your terminal to continue the session:\n\n<code>${command}</code>`,
321→        {
322→          message_thread_id: threadId,
323→          parse_mode: "HTML",
324→        },
325→      );
326→    });
327→
328→    // Setup message routing
329→    this.setupRoutes();
330→
331→    // Start bot polling
332→    this.bot.start({
333→      allowed_updates: ["message", "callback_query"],
334→      onStart: () =>
335→        log.info(
336→          { chatId: this.telegramConfig.chatId },
337→          "Telegram bot started",
338→        ),
339→    });
340→
341→    // Send welcome message
342→    try {
343→      const config = this.core.configManager.get();
344→      const agents = this.core.agentManager.getAvailableAgents();
345→      const allRecords = this.core.sessionManager.listRecords();
346→
347→      const welcomeText = buildWelcomeMessage({
348→        activeCount: allRecords.filter(r => r.status === 'active' || r.status === 'initializing').length,
349→        errorCount: allRecords.filter(r => r.status === 'error').length,
350→        totalCount: allRecords.length,
351→        agents: agents.map(a => a.name),
352→        defaultAgent: config.defaultAgent,
353→      });
354→
355→      await this.bot.api.sendMessage(this.telegramConfig.chatId, welcomeText, {
356→        message_thread_id: this.assistantTopicId,
357→        parse_mode: "HTML",
358→        reply_markup: buildMenuKeyboard(),
359→      });
360→    } catch (err) {
361→      log.warn({ err }, "Failed to send welcome message");
362→    }
363→
364→    // Spawn assistant in background
365→    try {
366→      log.info("Spawning assistant session...");
367→      const { session, ready } = await spawnAssistant(
368→        this.core as OpenACPCore,
369→        this,
370→        this.assistantTopicId,
371→      );
372→      this.assistantSession = session;
373→      this.assistantInitializing = true;
374→      log.info({ sessionId: session.id }, "Assistant session ready, system prompt running in background");
375→      ready.then(() => {
376→        this.assistantInitializing = false;
377→        log.info({ sessionId: session.id }, "Assistant ready for user messages");
378→      });
379→    } catch (err) {
380→      log.error({ err }, "Failed to spawn assistant");
381→      this.bot.api.sendMessage(
382→        this.telegramConfig.chatId,
383→        `⚠️ <b>Failed to start assistant session.</b>\n\n<code>${err instanceof Error ? err.message : String(err)}</code>`,
384→        { message_thread_id: this.assistantTopicId, parse_mode: "HTML" },
385→      ).catch(() => {});
386→    }
387→  }
