397→  private setupRoutes(): void {
398→    this.bot.on("message:text", async (ctx) => {
399→      const threadId = ctx.message.message_thread_id;
400→      const text = ctx.message.text;
401→
402→      // Check for pending workspace input from interactive /new flow
403→      if (await handlePendingWorkspaceInput(ctx, this.core, this.telegramConfig.chatId, this.assistantTopicId)) {
404→        return;
405→      }
406→
407→      // General topic or no thread → redirect to assistant
408→      if (!threadId) {
409→        const html = redirectToAssistant(
410→          this.telegramConfig.chatId,
411→          this.assistantTopicId,
412→        );
413→        await ctx.reply(html, { parse_mode: "HTML" });
414→        return;
415→      }
416→
417→      // Notification topic → ignore
418→      if (threadId === this.notificationTopicId) return;
419→
420→      // Strip leading "/" from unrecognized commands — registered commands
421→      // (e.g. /new, /cancel) are already handled by bot.command() above.
422→      // Unrecognized slash commands can cause agent subprocesses to hang.
423→      const forwardText = text.startsWith("/") ? text.slice(1) : text;
424→
425→      // Assistant topic → forward to assistant session
426→      if (threadId === this.assistantTopicId) {
427→        if (!this.assistantSession) {
428→          await ctx.reply("⚠️ Assistant is not available yet. Please try again shortly.", { parse_mode: "HTML" });
429→          return;
430→        }
431→        await this.draftManager.finalize(this.assistantSession.id, this.assistantSession.id);
432→        ctx.replyWithChatAction("typing").catch(() => {});
433→        handleAssistantMessage(this.assistantSession, forwardText).catch(
434→          (err) => log.error({ err }, "Assistant error"),
435→        );
436→        return;
437→      }
438→
439→      // Session topic → forward to core
440→      const sessionId = this.core.sessionManager.getSessionByThread("telegram", String(threadId))?.id;
441→      if (sessionId) await this.draftManager.finalize(sessionId, this.assistantSession?.id);
442→      if (sessionId) {
443→        const tracker = this.sessionTrackers.get(sessionId);
444→        if (tracker) await tracker.onNewPrompt();
445→      }
446→      ctx.replyWithChatAction("typing").catch(() => {});
447→      this.core
448→        .handleMessage({
449→          channelId: "telegram",
450→          threadId: String(threadId),
451→          userId: String(ctx.from.id),
452→          text: forwardText,
453→        })
454→        .catch((err) => log.error({ err }, "handleMessage error"));
455→    });
456→
457→    // --- Incoming media handlers ---
458→
459→    this.bot.on("message:photo", async (ctx) => {
