522→  private messageHandlers: MessageHandlers<TelegramMessageCtx> = {
523→    onThought: async (ctx, _content) => {
524→      const tracker = this.getOrCreateTracker(ctx.sessionId, ctx.threadId);
525→      await tracker.onThought();
526→    },
527→
528→    onText: async (ctx, content) => {
529→      // CRITICAL: This handler must be fully synchronous to preserve text ordering.
530→      // sendMessage() is not awaited in wireSessionEvents, so multiple text events
531→      // run concurrently. Any await here creates a gap where subsequent text events
532→      // process first, causing out-of-order buffer accumulation.
533→      if (!this.draftManager.hasDraft(ctx.sessionId)) {
534→        const tracker = this.getOrCreateTracker(ctx.sessionId, ctx.threadId);
535→        tracker.onTextStart().catch(() => {}); // Fire-and-forget, no await
536→      }
537→      const draft = this.draftManager.getOrCreate(ctx.sessionId, ctx.threadId);
538→      draft.append(content.text);
539→      this.draftManager.appendText(ctx.sessionId, content.text);
540→    },
541→
542→    onToolCall: async (ctx, content) => {
543→      const tracker = this.getOrCreateTracker(ctx.sessionId, ctx.threadId);
544→      await tracker.onToolCall();
545→      await this.draftManager.finalize(ctx.sessionId, this.assistantSession?.id);
546→      const meta = content.metadata as ToolCallMetadata | undefined;
547→      await this.toolTracker.trackNewCall(ctx.sessionId, ctx.threadId, {
548→        ...meta!,
549→      });
550→    },
551→
552→    onToolUpdate: async (ctx, content) => {
553→      const meta = content.metadata as ToolUpdateMetadata | undefined;
554→      await this.toolTracker.updateCall(ctx.sessionId, {
555→        ...meta!,
556→      });
557→    },
558→
559→    onPlan: async (ctx, content) => {
560→      const meta = content.metadata as PlanMetadata | undefined;
