932→
933→    // 5. Create new topic — wrapped in try/catch for orphan recovery
934→    let newTopicId: number;
935→    try {
936→      newTopicId = await createSessionTopic(this.bot, chatId, `🔄 ${rawName}`);
937→    } catch (createErr) {
938→      // Critical: old topic deleted but new one failed — session is orphaned
939→      session.archiving = false;
940→      core.notificationManager.notifyAll({
941→        sessionId: session.id,
942→        sessionName: session.name,
943→        type: "error",
944→        summary: `Topic recreation failed for session "${rawName}". Session is orphaned. Error: ${(createErr as Error).message}`,
945→      });
946→      throw createErr;
947→    }
948→
949→    // 6. Rewire session to new topic
950→    session.threadId = String(newTopicId);
951→
952→    // 7. Persist via patchRecord — spread existing platform data, explicitly delete old skillMsgId
953→    const existingRecord = core.sessionManager.getSessionRecord(session.id);
954→    const existingPlatform = { ...(existingRecord?.platform ?? {}) };
955→    delete (existingPlatform as Record<string, unknown>).skillMsgId;
956→    await core.sessionManager.patchRecord(session.id, {
957→      platform: { ...existingPlatform, topicId: newTopicId },
958→    });
959→
960→    // 8. Clear archiving flag
961→    session.archiving = false;
962→
963→    return { newThreadId: String(newTopicId) };
964→  }
965→}
