import type { Attachment } from '../../core/types.js'
import { log } from '../../core/log.js'

const MAX_DOWNLOAD_SIZE = 100 * 1024 * 1024 // 100MB safety cap for downloads
const DISCORD_UPLOAD_LIMIT = 25 * 1024 * 1024 // 25MB — Discord free tier

/**
 * Check if an attachment exceeds Discord's upload limit.
 */
export function isAttachmentTooLarge(size: number): boolean {
  return size > DISCORD_UPLOAD_LIMIT
}

/**
 * Classify a MIME contentType string into an Attachment type.
 */
export function classifyAttachmentType(
  contentType: string | null | undefined,
): Attachment['type'] {
  if (!contentType) return 'file'
  if (contentType.startsWith('image/')) return 'image'
  if (contentType.startsWith('audio/')) return 'audio'
  return 'file'
}

/**
 * Build fallback text when message.content is empty but attachments exist.
 * Mirrors Telegram adapter's pattern: [Photo: filename], [Audio: filename], [File: filename]
 */
export function buildFallbackText(
  attachments: Array<{ type: Attachment['type']; fileName: string }>,
): string {
  return attachments
    .map((att) => {
      const label = att.type === 'image' ? 'Photo' : att.type === 'audio' ? 'Audio' : 'File'
      return `[${label}: ${att.fileName}]`
    })
    .join(' ')
}

/**
 * Download a file from a Discord attachment URL.
 * Returns the buffer or null on failure.
 */
export async function downloadDiscordAttachment(
  url: string,
  fileName: string,
): Promise<Buffer | null> {
  try {
    const response = await fetch(url)
    if (!response.ok) {
      log.warn({ url, status: response.status, fileName }, '[discord-media] Download failed')
      return null
    }
    const buffer = Buffer.from(await response.arrayBuffer())
    if (buffer.length > MAX_DOWNLOAD_SIZE) {
      log.warn({ fileName, size: buffer.length }, '[discord-media] File exceeds download size cap')
      return null
    }
    return buffer
  } catch (err) {
    log.error({ err, url, fileName }, '[discord-media] Download error')
    return null
  }
}

import type { ChatInputCommandInteraction, ButtonInteraction } from 'discord.js'
import { log } from '../../../core/log.js'
import type { DiscordAdapter } from '../adapter.js'

import { handleNew, handleNewChat, handleNewSessionButton } from './new-session.js'
import { handleCancel, handleStatus, handleSessions, handleHandoff, handleCleanupButton } from './session.js'
import { handleDangerous, handleDangerousButton, handleRestart, handleUpdate } from './admin.js'
import { handleMenu, handleHelp, handleClear, handleMenuButton } from './menu.js'
import { handleAgents, handleInstall, handleAgentButton } from './agents.js'
import { handleDoctor, handleDoctorButton } from './doctor.js'
import { handleIntegrate, handleIntegrateButton } from './integrate.js'
import { handleSettings, handleSettingsButton } from './settings.js'

export async function handleSlashCommand(
  interaction: ChatInputCommandInteraction,
  adapter: DiscordAdapter,
): Promise<void> {
  const { commandName } = interaction

  try {
    switch (commandName) {
      case 'new':
        await handleNew(interaction, adapter)
        break
      case 'newchat':
        await handleNewChat(interaction, adapter)
        break
      case 'cancel':
        await handleCancel(interaction, adapter)
        break
      case 'status':
        await handleStatus(interaction, adapter)
        break
      case 'sessions':
        await handleSessions(interaction, adapter)
        break
      case 'agents':
        await handleAgents(interaction, adapter)
        break
      case 'install':
        await handleInstall(interaction, adapter)
        break
      case 'menu':
        await handleMenu(interaction, adapter)
        break
      case 'help':
        await handleHelp(interaction, adapter)
        break
      case 'dangerous':
        await handleDangerous(interaction, adapter)
        break
      case 'restart':
        await handleRestart(interaction, adapter)
        break
      case 'update':
        await handleUpdate(interaction, adapter)
        break
      case 'integrate':
        await handleIntegrate(interaction, adapter)
        break
      case 'settings':
        await handleSettings(interaction, adapter)
        break
      case 'doctor':
        await handleDoctor(interaction, adapter)
        break
      case 'handoff':
        await handleHandoff(interaction, adapter)
        break
      case 'clear':
        await handleClear(interaction, adapter)
        break
      default:
        log.warn({ commandName }, '[discord-router] Unknown slash command')
        if (!interaction.replied && !interaction.deferred) {
          await interaction.reply({ content: `Unknown command: /${commandName}`, ephemeral: true })
        }
    }
  } catch (err) {
    log.error({ err, commandName }, '[discord-router] Slash command handler failed')
    try {
      const errMsg = `❌ Command failed: ${err instanceof Error ? err.message : String(err)}`
      if (interaction.deferred) {
        await interaction.editReply(errMsg)
      } else if (!interaction.replied) {
        await interaction.reply({ content: errMsg, ephemeral: true })
      }
    } catch { /* ignore reply errors */ }
  }
}

export async function setupButtonCallbacks(
  interaction: ButtonInteraction,
  adapter: DiscordAdapter,
): Promise<void> {
  const { customId } = interaction

  try {
    // Ordered from most specific to least specific
    if (customId.startsWith('a:dismiss:')) {
      // Action dismiss button — remove buttons from the message
      try { await interaction.update({ components: [] }) } catch { /* ignore */ }
      return
    }

    if (customId.startsWith('a:')) {
      // Action confirm button (new session or cancel from assistant suggestions)
      const { getAction, removeAction } = await import('../action-detect.js')
      const actionId = customId.slice(2)
      const action = getAction(actionId)
      if (!action) {
        await interaction.reply({ content: '❌ Action expired.', ephemeral: true })
        return
      }
      removeAction(actionId)
      if (action.type === 'new_session') {
        await executeNewSession(interaction, adapter, action.agent, action.workspace)
      } else if (action.type === 'cancel_session') {
        await executeCancelSession(interaction, adapter)
      }
      return
    }

    if (customId.startsWith('d:')) {
      await handleDangerousButton(interaction, adapter)
      return
    }

    if (customId.startsWith('m:new:')) {
      await handleNewSessionButton(interaction, adapter)
      return
    }

    if (customId === 'm:cleanup' || customId.startsWith('m:cleanup:')) {
      await handleCleanupButton(interaction, adapter)
      return
    }

    if (customId === 'm:doctor' || customId.startsWith('m:doctor:')) {
      await handleDoctorButton(interaction, adapter)
      return
    }

    if (customId.startsWith('ag:')) {
      await handleAgentButton(interaction, adapter)
      return
    }

    if (customId.startsWith('na:')) {
      // New session with specific agent (from install confirmation)
      const agentKey = customId.slice(3)
      try { await interaction.deferReply({ ephemeral: true }) } catch { /* ignore */ }
      await executeNewSession(interaction, adapter, agentKey, undefined)
      return
    }

    if (customId.startsWith('s:')) {
      await handleSettingsButton(interaction, adapter)
      return
    }

    if (customId.startsWith('i:')) {
      await handleIntegrateButton(interaction, adapter)
      return
    }

    // Catch-all m: handler
    if (customId.startsWith('m:')) {
      await handleMenuButton(interaction, adapter)
      return
    }

    log.warn({ customId }, '[discord-router] Unhandled button interaction')
  } catch (err) {
    log.error({ err, customId }, '[discord-router] Button callback failed')
    try {
      const errMsg = `❌ Action failed: ${err instanceof Error ? err.message : String(err)}`
      if (!interaction.replied && !interaction.deferred) {
        await interaction.reply({ content: errMsg, ephemeral: true })
      } else {
        await interaction.followUp({ content: errMsg, ephemeral: true })
      }
    } catch { /* ignore reply errors */ }
  }
}

// Helper: execute new session from button interaction
async function executeNewSession(
  interaction: ButtonInteraction,
  adapter: DiscordAdapter,
  agentName?: string,
  workspace?: string,
): Promise<void> {
  const { executeNewSession: doExecute } = await import('./new-session.js')
  await doExecute(interaction, adapter, agentName, workspace)
}

// Helper: execute cancel session from button interaction
async function executeCancelSession(
  interaction: ButtonInteraction,
  adapter: DiscordAdapter,
): Promise<void> {
  const { executeCancelSession: doCancel } = await import('./session.js')
  await doCancel(interaction, adapter)
}

import { describe, it, expect, vi, afterEach } from 'vitest'
import { classifyAttachmentType, buildFallbackText, isAttachmentTooLarge, downloadDiscordAttachment } from './media.js'

describe('classifyAttachmentType', () => {
  it('classifies image/* as image', () => {
    expect(classifyAttachmentType('image/png')).toBe('image')
    expect(classifyAttachmentType('image/jpeg')).toBe('image')
    expect(classifyAttachmentType('image/webp')).toBe('image')
  })

  it('classifies audio/* as audio', () => {
    expect(classifyAttachmentType('audio/ogg')).toBe('audio')
    expect(classifyAttachmentType('audio/mpeg')).toBe('audio')
  })

  it('classifies other types as file', () => {
    expect(classifyAttachmentType('application/pdf')).toBe('file')
    expect(classifyAttachmentType('video/mp4')).toBe('file')
    expect(classifyAttachmentType('text/plain')).toBe('file')
  })

  it('defaults to file for null/undefined contentType', () => {
    expect(classifyAttachmentType(null)).toBe('file')
    expect(classifyAttachmentType(undefined)).toBe('file')
  })
})

describe('buildFallbackText', () => {
  it('generates text from single attachment', () => {
    expect(buildFallbackText([{ type: 'image', fileName: 'photo.png' }]))
      .toBe('[Photo: photo.png]')
  })

  it('generates text from audio attachment', () => {
    expect(buildFallbackText([{ type: 'audio', fileName: 'voice.wav' }]))
      .toBe('[Audio: voice.wav]')
  })

  it('generates text from file attachment', () => {
    expect(buildFallbackText([{ type: 'file', fileName: 'doc.pdf' }]))
      .toBe('[File: doc.pdf]')
  })

  it('joins multiple attachments', () => {
    const result = buildFallbackText([
      { type: 'image', fileName: 'a.png' },
      { type: 'file', fileName: 'b.pdf' },
    ])
    expect(result).toBe('[Photo: a.png] [File: b.pdf]')
  })
})

describe('isAttachmentTooLarge', () => {
  it('returns false for files under 25MB', () => {
    expect(isAttachmentTooLarge(1024)).toBe(false)
    expect(isAttachmentTooLarge(25 * 1024 * 1024)).toBe(false)
  })

  it('returns true for files over 25MB', () => {
    expect(isAttachmentTooLarge(25 * 1024 * 1024 + 1)).toBe(true)
    expect(isAttachmentTooLarge(50 * 1024 * 1024)).toBe(true)
  })
})

describe('downloadDiscordAttachment', () => {
  const originalFetch = globalThis.fetch

  afterEach(() => {
    globalThis.fetch = originalFetch
  })

  it('returns null on 404', async () => {
    globalThis.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 404,
    }) as unknown as typeof fetch

    const result = await downloadDiscordAttachment('https://cdn.example.com/file.png', 'file.png')
    expect(result).toBeNull()
  })

  it('returns null on network error', async () => {
    globalThis.fetch = vi.fn().mockRejectedValue(new Error('Network error')) as unknown as typeof fetch

    const result = await downloadDiscordAttachment('https://cdn.example.com/file.png', 'file.png')
    expect(result).toBeNull()
  })

  it('returns buffer on success', async () => {
    const fakeData = new Uint8Array([1, 2, 3])
    globalThis.fetch = vi.fn().mockResolvedValue({
      ok: true,
      arrayBuffer: () => Promise.resolve(fakeData.buffer),
    }) as unknown as typeof fetch

    const result = await downloadDiscordAttachment('https://cdn.example.com/file.png', 'file.png')
    expect(result).toBeInstanceOf(Buffer)
    expect(result!.length).toBe(3)
  })
})

